{
  "name": "gpu-price-schema-v1",
  "schema": "gpu-price-schema-v1",
  "urlPattern": "^https://example\\.test/gpu-\\d+$",
  "selectors": {
    "product_id": {
      "selector": "body",
      "attribute": "data-product-id",
      "priority": 1,
      "fallback": [
        {
          "selector": "meta[property=\"og:url\"]",
          "attribute": "content"
        },
        {
          "regex": "/gpu-(\\d+)$",
          "selector": "body"
        }
      ]
    },
    "title": {
      "selector": "h1.product-title",
      "text": true,
      "normalize": true
    },
    "price": {
      "selector": "span.price",
      "text": true,
      "normalize": true,
      "parse": {
        "type": "decimal",
        "regex": "\\$?([0-9,\\.]+)",
        "group": 1
      },
      "fallback": [
        {
          "selector": "meta[property=\"product:price:amount\"]",
          "attribute": "content",
          "parse": {
            "type": "decimal",
            "group": 1
          }
        }
      ]
    },
    "availability": {
      "selector": "div.availability span",
      "text": true,
      "normalize": true,
      "map": {
