            "normalize": true,
            "convert": "float"
          }
        }
      ]
    },
    "url": {
      "selector": "",
      "value": "$(url)"
    }
  },
  "globalPreprocess": [
    {
      "action": "trim",
      "fields": ["title", "availability"]
    }
  ]
}
